using Microsoft.EntityFrameworkCore;using Visitors.Api.Data;using Visitors.Api.Models;
namespace Visitors.Api.Services;
public sealed class VisitService(VisitorsDbContext db){public async Task<Visit> CheckInAsync(int id,string badge,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(badge))throw new ArgumentException("Badge number is required.");await using var tx=await db.Database.BeginTransactionAsync(ct);var v=await db.Visits.SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(v.Status!=VisitStatuses.Expected)throw new InvalidOperationException("Only expected visits can check in.");if(v.ScheduledAt.Date!=DateTime.UtcNow.Date)throw new InvalidOperationException("Check-in is only allowed on the scheduled day.");if(await db.Visits.AnyAsync(x=>x.BadgeNumber==badge&&x.Status==VisitStatuses.CheckedIn,ct))throw new InvalidOperationException("Badge is already in use.");v.BadgeNumber=badge.Trim().ToUpperInvariant();v.Status=VisitStatuses.CheckedIn;v.CheckedInAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return v;}
public async Task<Visit> CheckOutAsync(int id,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var v=await db.Visits.SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(v.Status!=VisitStatuses.CheckedIn)throw new InvalidOperationException("Only checked-in visits can check out.");v.Status=VisitStatuses.CheckedOut;v.CheckedOutAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return v;}}
